"use client";

import { motion, useInView, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type RefObject, useRef } from "react";

import { cn } from "@/lib/utils";

/** Props for a phrase with a highlighter stroke that draws itself behind it. */
export type MarkerTextProps = ComponentPropsWithoutRef<"mark"> & {
  /**
   * Draws or clears the stroke on demand. Leave it out and the stroke draws
   * once, the first time the phrase scrolls into view.
   */
  shown?: boolean;
  /** The element that scrolls, when it is not the page. */
  root?: RefObject<HTMLElement | null>;
  /** Classes for the stroke, such as another tint. Check the text still reads at 4.5 to 1 on it. */
  strokeClassName?: string;
};

// The system points at a phrase once, so the stroke is an ease-out that lands.
const DRAW: Transition = { duration: 0.5, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

// The clip is rounded too, so the leading edge of the stroke is round while it draws.
const HIDDEN = "inset(0% 100% 0% 0% round 0.375rem)";
const DRAWN = "inset(0% 0% 0% 0% round 0.375rem)";

/**
 * Draws a highlighter stroke behind a short phrase, left to right, when the
 * phrase scrolls into view or when `shown` turns true. The stroke is a tint of
 * the primary colour behind text in the foreground colour, so the phrase reads
 * the same in both themes. The text is never hidden, and with reduced motion
 * the stroke is simply there.
 */
export function MarkerText({ shown, root, strokeClassName, className, children, ...markProps }: MarkerTextProps) {
  const reduceMotion = useReducedMotion();
  const phrase = useRef<HTMLElement>(null);
  const seen = useInView(phrase, { once: true, amount: 0.8, root });
  const drawn = shown ?? seen;

  return (
    // The element is a real `mark`. Its default colours are cleared, because the stroke replaces them.
    <mark
      {...markProps}
      ref={phrase}
      data-drawn={drawn ? "true" : "false"}
      className={cn("relative isolate inline-block bg-transparent text-foreground", className)}
    >
      <motion.span
        aria-hidden="true"
        data-stroke=""
        initial={false}
        animate={{ clipPath: drawn ? DRAWN : HIDDEN }}
        transition={reduceMotion ? INSTANT : DRAW}
        // A round-ended band, leaning one degree like a stroke made by hand.
        className={cn("absolute -inset-x-1 inset-y-0.5 -z-10 -rotate-1 rounded-md bg-primary/25", strokeClassName)}
      />
      {children}
    </mark>
  );
}
